"""Archive-first robot asset index support for the PuddleDuck web runtime.

A robot directory containing ``.puddleduck`` is treated as an immutable packed
robot deployment.  Its URDFs and assets are read from
``.puddleduck/urdf-packs/index.json`` and the referenced ZIP.  A directory
without ``.puddleduck`` remains a development/legacy robot directory whose
loose URDF files are discovered by ``broadcast_state``.
"""

from __future__ import annotations

import hashlib
import json
import zipfile
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Mapping, Sequence

PACK_DIR_REL = Path(".puddleduck") / "urdf-packs"
PACK_INDEX_REL = PACK_DIR_REL / "index.json"
PACK_INDEX_FORMAT = "puddleduck-urdf-pack-index"
PACK_INDEX_SCHEMAS = {1, 2}
PACK_MANIFEST = "manifest.json"
PACK_FORMAT = "puddleduck-urdf-pack"
PACK_SCHEMAS = {1, 2}


class RobotPackError(RuntimeError):
    """The directory opted into packed assets but its pack is unusable."""


@dataclass(frozen=True)
class PackedRobotUrdf:
    robot: str
    robot_dir: Path
    index_path: Path
    archive_path: Path
    urdf_name: str
    duck: str
    asset_version: str
    archive_schema: int
    archive_size: int
    archive_sha256: str
    file_count: int
    asset_count: int
    uncompressed_size: int
    urdf_sha256: str
    urdf_text: str
    index: Mapping[str, Any]
    entry: Mapping[str, Any]
    manifest: Mapping[str, Any]


def _simple_name(value: Any, *, description: str) -> str:
    name = str(value or "").strip()
    if not name or Path(name).name != name:
        raise RobotPackError(f"invalid {description} in robot pack index: {name!r}")
    return name


def has_packed_layout(robot_dir: str | Path) -> bool:
    return (Path(robot_dir) / ".puddleduck").is_dir()


def load_robot_pack_index(robot_dir: str | Path) -> dict[str, Any] | None:
    """Load a robot index, or return ``None`` for a loose development tree.

    The presence of ``.puddleduck`` is an explicit layout marker.  Once that
    marker exists we do not silently fall back to loose files: a missing or
    malformed index raises :class:`RobotPackError` so broken deployments are
    visible instead of being masked by stale files.
    """

    robot_path = Path(robot_dir).expanduser().resolve()
    if not has_packed_layout(robot_path):
        return None

    index_path = robot_path / PACK_INDEX_REL
    if not index_path.is_file():
        raise RobotPackError(
            f"packed robot directory is missing {PACK_INDEX_REL.as_posix()}: {robot_path}"
        )
    try:
        doc = json.loads(index_path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise RobotPackError(f"invalid robot pack index {index_path}: {exc}") from exc
    if not isinstance(doc, dict):
        raise RobotPackError(f"robot pack index root must be an object: {index_path}")
    if doc.get("format") != PACK_INDEX_FORMAT:
        raise RobotPackError(
            f"unsupported robot pack index format {doc.get('format')!r}: {index_path}"
        )
    if int(doc.get("schema") or 0) not in PACK_INDEX_SCHEMAS:
        raise RobotPackError(
            f"unsupported robot pack index schema {doc.get('schema')!r}: {index_path}"
        )
    if not isinstance(doc.get("packs"), dict) or not doc["packs"]:
        raise RobotPackError(f"robot pack index contains no URDF packs: {index_path}")
    return doc


def _load_manifest(archive: zipfile.ZipFile, archive_path: Path) -> dict[str, Any]:
    try:
        manifest = json.loads(archive.read(PACK_MANIFEST).decode("utf-8"))
    except Exception as exc:
        raise RobotPackError(f"invalid manifest in {archive_path}: {exc}") from exc
    if not isinstance(manifest, dict):
        raise RobotPackError(f"robot pack manifest root must be an object: {archive_path}")
    if manifest.get("format") != PACK_FORMAT:
        raise RobotPackError(
            f"unsupported robot pack format {manifest.get('format')!r}: {archive_path}"
        )
    if int(manifest.get("schema") or 0) not in PACK_SCHEMAS:
        raise RobotPackError(
            f"unsupported robot pack schema {manifest.get('schema')!r}: {archive_path}"
        )
    return manifest


def select_packed_urdf(
    robot_dir: str | Path,
    candidate_names: Sequence[str],
    *,
    requested_duck: str = "",
) -> PackedRobotUrdf | None:
    """Select and read one URDF from a packed robot directory.

    ``None`` means the directory has no ``.puddleduck`` marker and should be
    handled as a loose development tree.  A marked but invalid directory raises
    :class:`RobotPackError`.
    """

    robot_path = Path(robot_dir).expanduser().resolve()
    index = load_robot_pack_index(robot_path)
    if index is None:
        return None

    packs = index["packs"]
    selected_key = ""
    wanted_duck = str(requested_duck or "").strip().lower()
    if wanted_duck and wanted_duck != "auto":
        matches = [
            str(name)
            for name, value in packs.items()
            if isinstance(value, dict)
            and str(value.get("duck") or "").strip().lower() == wanted_duck
        ]
        if len(matches) == 1:
            selected_key = matches[0]
        elif len(matches) > 1:
            raise RobotPackError(
                f"robot pack index has multiple URDF entries for duck={wanted_duck}: "
                + ", ".join(sorted(matches))
            )

    if not selected_key:
        for raw_name in candidate_names:
            name = str(raw_name or "").strip()
            if name and name in packs:
                selected_key = name
                break

    if not selected_key:
        default_entry = index.get("urdf") if isinstance(index.get("urdf"), dict) else {}
        default_name = str(default_entry.get("default_urdf") or "").strip()
        if default_name in packs:
            selected_key = default_name

    if not selected_key:
        requested = ", ".join(str(name) for name in candidate_names if str(name).strip())
        raise RobotPackError(
            f"robot pack index has no requested URDF ({requested or 'no candidates'}): "
            f"{robot_path / PACK_INDEX_REL}"
        )

    entry = packs.get(selected_key)
    if not isinstance(entry, dict):
        raise RobotPackError(f"invalid URDF pack entry for {selected_key!r}")

    urdf_name = _simple_name(entry.get("urdf") or selected_key, description="URDF member")
    archive_name = _simple_name(entry.get("archive"), description="archive name")
    pack_root = (robot_path / PACK_DIR_REL).resolve()
    archive_path = (pack_root / archive_name).resolve()
    if pack_root not in archive_path.parents or not archive_path.is_file():
        raise RobotPackError(f"robot asset archive not found: {archive_path}")

    expected_size = int(entry.get("archive_size") or 0)
    actual_size = int(archive_path.stat().st_size)
    if expected_size > 0 and actual_size != expected_size:
        raise RobotPackError(
            f"robot asset archive size mismatch for {archive_name}: {actual_size} != {expected_size}"
        )

    asset_version = str(entry.get("asset_version") or "").strip()
    if not asset_version:
        raise RobotPackError(f"robot pack entry has no asset_version: {selected_key}")

    try:
        with zipfile.ZipFile(archive_path) as archive:
            manifest = _load_manifest(archive, archive_path)
            if str(manifest.get("asset_version") or "") != asset_version:
                raise RobotPackError(
                    f"robot pack version mismatch: {manifest.get('asset_version')} != {asset_version}"
                )
            declared_urdfs = {
                str(name) for name in (manifest.get("urdfs") or []) if str(name).strip()
            }
            if declared_urdfs and urdf_name not in declared_urdfs:
                raise RobotPackError(
                    f"robot pack does not declare selected URDF {urdf_name}: {archive_path}"
                )
            try:
                urdf_bytes = archive.read(urdf_name)
            except KeyError as exc:
                raise RobotPackError(
                    f"robot asset archive is missing selected URDF {urdf_name}: {archive_path}"
                ) from exc
    except zipfile.BadZipFile as exc:
        raise RobotPackError(f"invalid robot asset ZIP {archive_path}: {exc}") from exc

    expected_urdf_sha = str(entry.get("urdf_sha256") or "").strip().lower()
    actual_urdf_sha = hashlib.sha256(urdf_bytes).hexdigest()
    if expected_urdf_sha and actual_urdf_sha != expected_urdf_sha:
        raise RobotPackError(
            f"packed URDF hash mismatch for {urdf_name}: {actual_urdf_sha} != {expected_urdf_sha}"
        )
    try:
        urdf_text = urdf_bytes.decode("utf-8")
    except UnicodeDecodeError:
        urdf_text = urdf_bytes.decode("utf-8", errors="replace")

    robot = str(index.get("robot") or manifest.get("robot") or robot_path.name).strip()
    return PackedRobotUrdf(
        robot=robot or robot_path.name,
        robot_dir=robot_path,
        index_path=robot_path / PACK_INDEX_REL,
        archive_path=archive_path,
        urdf_name=urdf_name,
        duck=str(entry.get("duck") or "").strip().lower(),
        asset_version=asset_version,
        archive_schema=max(1, int(entry.get("archive_schema") or manifest.get("schema") or 1)),
        archive_size=actual_size,
        archive_sha256=str(entry.get("archive_sha256") or "").strip().lower(),
        file_count=max(0, int(entry.get("file_count") or len(manifest.get("files") or []))),
        asset_count=max(0, int(entry.get("asset_count") or 0)),
        uncompressed_size=max(0, int(entry.get("uncompressed_size") or manifest.get("total_bytes") or 0)),
        urdf_sha256=expected_urdf_sha or actual_urdf_sha,
        urdf_text=urdf_text,
        index=index,
        entry=entry,
        manifest=manifest,
    )
